import sys
from functools import reduce

def solve(u, v):
    if u == 0 and v == 0:
        return []
    if u == 0:
        return [-1]
    if v == 0:
        return [-1]

    # Try to construct the array
    result = []
    for i in range(64):
        if (u >> i) & 1:
            result.append(1 << i)
            v -= (1 << i)

    if v < 0:
        return [-1]

    # Add remaining value as a single element
    if v > 0:
        result.append(v)

    # Check if the XOR of the result is u
    if reduce(lambda x, y: x ^ y, result) != u:
        return [-1]

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    u = int(data[0])
    v = int(data[1])

    result = solve(u, v)
    if result == -1:
        print("-1")
    else:
        print(len(result))
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
